mapper.update:
update ingestion_jobs
set status = 'PROCESSING',
    error_message = null,
    updated_at = #{updatedAt}
where id = #{jobId, jdbcType=OTHER, typeHandler=com.zhangspaghetti.babytalk.mybatis.UuidTypeHandler}

update ingestion_jobs
set status = 'COMPLETED',
    total_chunks = #{totalChunks},
    error_message = null,
    updated_at = #{updatedAt}
where id = #{jobId, jdbcType=OTHER, typeHandler=com.zhangspaghetti.babytalk.mybatis.UuidTypeHandler}

update ingestion_jobs
set status = 'FAILED',
    error_message = #{errorMessage},
    updated_at = #{updatedAt}
where id = #{jobId, jdbcType=OTHER, typeHandler=com.zhangspaghetti.babytalk.mybatis.UuidTypeHandler}

update ingestion_jobs
set status = 'PENDING',
    total_chunks = 0,
    updated_at = #{updatedAt}
where id = #{jobId, jdbcType=OTHER, typeHandler=com.zhangspaghetti.babytalk.mybatis.UuidTypeHandler}
